import 'dart:convert';
import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

/// Round button with a living 3D Earth: a sharp, bright satellite picture
/// (NASA Blue Marble) wrapped onto a real sphere, tilted like the real Earth,
/// lit by the sun, with a soft blue atmosphere. Used as the language switch.
class SpinningGlobe extends StatefulWidget {
  const SpinningGlobe({super.key, this.size = 44});

  final double size;

  @override
  State<SpinningGlobe> createState() => _SpinningGlobeState();
}

class _SpinningGlobeState extends State<SpinningGlobe> with SingleTickerProviderStateMixin {
  late final AnimationController _spin = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 18),
  )..repeat();
  ui.Image? _earth;

  @override
  void initState() {
    super.initState();
    _loadEarth().then((ui.Image image) {
      if (mounted) setState(() => _earth = image);
    }).catchError((Object _) {});
  }

  @override
  void dispose() {
    _spin.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final double s = widget.size;
    return Container(
      width: s,
      height: s,
      padding: const EdgeInsets.all(2),
      decoration: const BoxDecoration(
        shape: BoxShape.circle,
        color: Colors.white,
        boxShadow: <BoxShadow>[
          BoxShadow(color: Color(0x662A8CFF), blurRadius: 12, spreadRadius: 1, offset: Offset(0, 3)),
        ],
      ),
      child: RepaintBoundary(
        child: AnimatedBuilder(
          animation: _spin,
          builder: (BuildContext context, Widget? _) {
            return CustomPaint(
              size: Size(s - 4, s - 4),
              painter: _EarthPainter(_earth, _spin.value),
            );
          },
        ),
      ),
    );
  }
}

Future<ui.Image>? _earthFuture;

Future<ui.Image> _loadEarth() {
  return _earthFuture ??= () async {
    final ui.Codec codec = await ui.instantiateImageCodec(base64Decode(_earthJpg));
    final ui.FrameInfo frame = await codec.getNextFrame();
    return frame.image;
  }();
}

/// Draws the Earth as a true 3D sphere: a mesh of small triangles, each
/// carrying its piece of the world map, projected from a tilted ball.
/// [phase] (0..1) is how far the Earth has turned.
class _EarthPainter extends CustomPainter {
  _EarthPainter(this.image, this.phase);

  final ui.Image? image;
  final double phase;

  static const int _latSteps = 36;
  static const int _lonSteps = 72;
  static const double _tilt = 23.4 * math.pi / 180;
  static const double _pitch = 14 * math.pi / 180;

  @override
  void paint(Canvas canvas, Size size) {
    final double d = size.shortestSide;
    final double r = d / 2;
    final Offset c = Offset(r, r);
    final Rect ball = Rect.fromCircle(center: c, radius: r);

    canvas.save();
    canvas.clipPath(Path()..addOval(ball));

    // Deep ocean behind the picture (also shown while the picture loads).
    canvas.drawRect(
      ball,
      Paint()
        ..shader = const RadialGradient(
          center: Alignment(-0.3, -0.35),
          colors: <Color>[Color(0xFF3FA3FF), Color(0xFF0B4FA8)],
        ).createShader(ball),
    );

    final ui.Image? map = image;
    if (map != null) {
      _drawSphere(canvas, map, c, r);
    }

    // Sunlight from the upper left, night side on the lower right.
    canvas.drawRect(
      ball,
      Paint()
        ..shader = const RadialGradient(
          center: Alignment(-0.45, -0.5),
          radius: 1.15,
          colors: <Color>[Color(0x00FFFFFF), Color(0x00000000), Color(0x66020A1E)],
          stops: <double>[0, 0.55, 1],
        ).createShader(ball),
    );
    // Shiny highlight where the sun reflects in the ocean.
    canvas.drawCircle(
      c + Offset(-r * 0.38, -r * 0.42),
      r * 0.45,
      Paint()
        ..shader = RadialGradient(
          colors: const <Color>[Color(0x66FFFFFF), Color(0x00FFFFFF)],
        ).createShader(Rect.fromCircle(center: c + Offset(-r * 0.38, -r * 0.42), radius: r * 0.45)),
    );
    // Thin blue atmosphere at the edge of the ball.
    canvas.drawCircle(
      c,
      r,
      Paint()
        ..shader = const RadialGradient(
          colors: <Color>[Color(0x00000000), Color(0x00000000), Color(0x9966C8FF)],
          stops: <double>[0, 0.84, 1],
        ).createShader(ball),
    );
    canvas.restore();

    // Crisp outline so the ball stands out on the white ring.
    canvas.drawCircle(
      c,
      r - 0.4,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 0.8
        ..color = const Color(0x553C9BFF),
    );
  }

  void _drawSphere(Canvas canvas, ui.Image map, Offset c, double r) {
    final double iw = map.width.toDouble();
    final double ih = map.height.toDouble();
    // Longitude facing the viewer: the Earth turns west to east.
    final double center = -phase * 2 * math.pi;
    final double cosP = math.cos(_pitch);
    final double sinP = math.sin(_pitch);
    final double cosR = math.cos(_tilt);
    final double sinR = math.sin(_tilt);

    final int cols = _lonSteps + 1;
    final int rowsN = _latSteps + 1;
    final Float32List pos = Float32List(cols * rowsN * 2);
    final Float32List tex = Float32List(cols * rowsN * 2);
    final List<bool> front = List<bool>.filled(cols * rowsN, false);

    for (int i = 0; i < rowsN; i++) {
      final double lat = math.pi / 2 - i * math.pi / _latSteps;
      final double cl = math.cos(lat);
      final double sl = math.sin(lat);
      for (int j = 0; j < cols; j++) {
        final double dl = -math.pi + j * 2 * math.pi / _lonSteps;
        // Point on the ball (y up, z towards the viewer).
        double x = cl * math.sin(dl);
        double y = sl;
        double z = cl * math.cos(dl);
        // Tip the north pole slightly towards the viewer.
        final double y1 = y * cosP - z * sinP;
        final double z1 = y * sinP + z * cosP;
        y = y1;
        z = z1;
        // Lean the axis like the real Earth.
        final double x2 = x * cosR - y * sinR;
        final double y2 = x * sinR + y * cosR;
        x = x2;
        y = y2;
        final int k = i * cols + j;
        front[k] = z > 0;
        if (z <= 0) {
          // Points just behind the edge are pinned to the edge of the ball,
          // so the picture reaches the rim without gaps.
          final double len = math.sqrt(x * x + y * y);
          if (len > 0) {
            x /= len;
            y /= len;
          }
        }
        pos[k * 2] = c.dx + x * r;
        pos[k * 2 + 1] = c.dy - y * r;
        final double lon = center + dl;
        tex[k * 2] = (lon / (2 * math.pi) + 0.5) * iw;
        tex[k * 2 + 1] = (0.5 - lat / math.pi) * ih;
      }
    }

    final List<int> idx = <int>[];
    for (int i = 0; i < _latSteps; i++) {
      for (int j = 0; j < _lonSteps; j++) {
        final int a = i * cols + j;
        final int b = a + 1;
        final int e = a + cols;
        final int f = e + 1;
        if (!(front[a] || front[b] || front[e] || front[f])) continue;
        idx..add(a)..add(e)..add(b)..add(b)..add(e)..add(f);
      }
    }
    if (idx.isEmpty) return;

    final ui.Vertices vertices = ui.Vertices.raw(
      VertexMode.triangles,
      pos,
      textureCoordinates: tex,
      indices: Uint16List.fromList(idx),
    );
    final Paint p = Paint()
      ..filterQuality = FilterQuality.medium
      ..isAntiAlias = true
      ..shader = ImageShader(
        map,
        TileMode.repeated,
        TileMode.clamp,
        Matrix4.identity().storage,
        filterQuality: FilterQuality.medium,
      );
    canvas.drawVertices(vertices, BlendMode.srcOver, p);
  }

  @override
  bool shouldRepaint(covariant _EarthPainter oldDelegate) =>
      oldDelegate.phase != phase || oldDelegate.image != image;
}

